            p = new Portfolio(5);
        } else {
            p = new Portfolio(i);
        }
        region1.put(i, p);
        region2.put(i, p);
    }
    QueryService qs = CacheUtils.getQueryService();
    //create and execute query
    String queryString = "SELECT * from /portfolios1 P1, /portfolios2 P2 WHERE P1.ID = 5";
