@Test
public void testOrderByWithNullValuesUseIndex() throws Exception {
    // IN ORDER BY NULL values are treated as smallest. E.g For an ascending order by field
    // its null values are reported first and then the values in ascending order.
    String[] queries = { // 0 null values are first in the order.
    "SELECT  distinct * FROM /portfolio1 pf1 where ID > 0 order by pkid", //1 same as above.
    "SELECT  distinct * FROM /portfolio1 pf1 where ID > 0 order by pkid asc", //2 null values are last in the order.
    "SELECT  distinct * FROM /portfolio1 where ID > 0 order by pkid desc", //3 null values are first in the order.
    "SELECT  distinct pkid FROM /portfolio1 pf1 where ID > 0 order by pkid", //4
    "SELECT  distinct pkid FROM /portfolio1 pf1 where ID > 0 order by pkid asc", //5 null values are last in the order.
    "SELECT  distinct pkid FROM /portfolio1 pf1 where ID > 0 order by pkid desc", //6
