@Test
public void testConcurrentIndexMaintenanceForNoDeadlocks() throws Exception {
    System.getProperties().put("gemfire.AsynchIndexMaintenanceThreshold", "700");
    System.getProperties().put("gemfire.AsynchIndexMaintenanceInterval", "500");
    qs.createIndex("statusIndex", IndexType.FUNCTIONAL, "p.getID", "/portfolio p");
    final int TOTAL_THREADS = 25;
    final int NUM_UPDATES = 25;
    final CyclicBarrier barrier = new CyclicBarrier(TOTAL_THREADS);
    Thread[] threads = new Thread[TOTAL_THREADS];
    for (int i = 0; i < TOTAL_THREADS; ++i) {
        final int k = i;
        threads[i] = new Thread(new Runnable() {

            public void run() {
                try {
                    barrier.await();
                    for (int i = 0; i < NUM_UPDATES; ++i) {
                        try {
                            region.put("" + (k + 1), new Portfolio(k + 1));
                            Thread.sleep(10);
                        } catch (IllegalStateException ie) {
                            // If Asynchronous index queue is full. Retry.
                            if (ie.getMessage().contains("Queue full")) {
                                // retry
                                i--;
                                continue;
                            }
                            throw ie;
                        }
                    }
                } catch (Exception e) {
                    CacheUtils.getLogger().error(e);
                    exceptionOccured = true;
                }
            }
        });
    }
    for (int i = 0; i < TOTAL_THREADS; ++i) {
        threads[i].start();
    }
    try {
        for (int i = 0; i < TOTAL_THREADS; ++i) {
            ThreadUtils.join(threads[i], 30 * 1000);
        }
    } catch (Exception e) {
        CacheUtils.getLogger().error(e);
        exceptionOccured = true;
    }
    assertFalse(exceptionOccured);
}

@Test
public void testAsyncIndexUpdaterThreadShutdownForRR() {
    Cache cache = new CacheFactory().set("mcast-port", "0").create();
    RegionFactory rf = cache.createRegionFactory(RegionShortcut.REPLICATE);
    rf.setIndexMaintenanceSynchronous(false);
    Region localRegion = rf.create(name);
    assertNotNull("Region ref null", localRegion);
    try {
        cache.getQueryService().createIndex("idIndex", "ID", "/" + name);
    } catch (Exception e) {
        cache.close();
        e.printStackTrace();
        fail("Index creation failed");
    }
    for (int i = 0; i < 500; i++) {
        localRegion.put(i, new Portfolio(i));
    }
    GemFireCacheImpl internalCache = (GemFireCacheImpl) cache;
    // Don't disconnect distributed system yet to keep system thread groups alive.
    internalCache.close("Normal disconnect", null, false, false);
    // Get Asynchronous index updater thread group from Distributed System.
    ThreadGroup indexUpdaterThreadGroup = LoggingThreadGroup.getThreadGroup("QueryMonitor Thread Group");
    assertEquals(0, indexUpdaterThreadGroup.activeCount());
    internalCache.getSystem().disconnect();
}

