public void testStatsForRangeIndexAfterRecreate() throws Exception {
    keyIndex2 = (IndexProtocol) qs.createIndex("multiKeyIndex2", IndexType.FUNCTIONAL, "pos.secId", "/portfolio p, p.positions.values pos");
