    }
    // stop the locator
    try {
        if (pidLauncher == null) {
            assertEquals(Status.STOPPED, dirLauncher.stop().getStatus());
        } else {
            assertEquals(Status.STOPPED, pidLauncher.stop().getStatus());
        }
        waitForPidToStop(pid);
        waitForFileToDelete(this.pidFile);
    } catch (Throwable e) {
        this.errorCollector.addError(e);
    }
}

