                        ie.printStackTrace();
                    }
                    ((LocalRegion) region).notifyToRoll();
                }
            }
        });
        int thisRegionSize = startOperations(startKey, value);
        previousRegionSize = thisRegionSize;
        run[0] = false;
        th.join();
        tagmapInCache = saveVersionTags((LocalRegion) region);
        region.close();
    }
