/**
 * tests the blocking peek functionality of BlockingHARegionQueue
 */
@Test
public void testBlockQueue() {
    exceptionInThread = false;
    testFailed = false;
    try {
        final HARegionQueue bQ = HARegionQueue.getHARegionQueueInstance("testing", cache, HARegionQueue.BLOCKING_HA_QUEUE, false);
        Thread[] threads = new Thread[10];
        final CyclicBarrier barrier = new CyclicBarrier(threads.length + 1);
        for (int i = 0; i < threads.length; i++) {
            threads[i] = new Thread() {

                public void run() {
                    try {
                        barrier.await();
                        long startTime = System.currentTimeMillis();
                        Object obj = bQ.peek();
                        if (obj == null) {
                            testFailed = true;
                            message.append(" Failed :  failed since object was null and was not expected to be null \n");
                        }
                        long totalTime = System.currentTimeMillis() - startTime;
                        if (totalTime < 2000) {
                            testFailed = true;
                            message.append(" Failed :  Expected time to be greater than 2000 but it is not so ");
                        }
                    } catch (Exception e) {
                        exceptionInThread = true;
                        exception = e;
                    }
                }
            };
        }
        for (int k = 0; k < threads.length; k++) {
            threads[k].start();
        }
        barrier.await();
        Thread.sleep(5000);
        EventID id = new EventID(new byte[] { 1 }, 1, 1);
        bQ.put(new ConflatableObject("key", "value", id, false, "testing"));
        long startTime = System.currentTimeMillis();
        for (int k = 0; k < threads.length; k++) {
            ThreadUtils.join(threads[k], 60 * 1000);
        }
        long totalTime = System.currentTimeMillis() - startTime;
        if (totalTime >= 60000) {
            fail(" Test taken too long ");
        }
        if (testFailed) {
            fail(" test failed due to " + message);
        }
    } catch (Exception e) {
        e.printStackTrace();
        fail(" Test failed due to " + e);
    }
}

