        region.put("key3", val);
        cache.getLogger().info("waiting for compaction");
        synchronized (lock) {
            if (!okToExit[0]) {
                lock.wait(9000);
                assertTrue(okToExit[0]);
            }
            assertFalse(exceptionOccured[0]);
        }
        region.close();
    } finally {
        LocalRegion.ISSUE_CALLBACKS_TO_CACHE_OBSERVER = false;
        CacheObserverHolder.setInstance(old);
    }
}

