@Test
public void testLocalConcurrentMapOps() throws Exception {
    PartitionAttributesFactory paf = new PartitionAttributesFactory();
    Properties globalProps = new Properties();
    globalProps.put(PartitionAttributesFactory.GLOBAL_MAX_BUCKETS_PROPERTY, "100");
    PartitionAttributes pa = paf.setRedundantCopies(0).setLocalMaxMemory(100).create();
    AttributesFactory af = new AttributesFactory();
    af.setPartitionAttributes(pa);
    RegionAttributes ra = af.create();
    PartitionedRegion pr = null;
    pr = (PartitionedRegion) cache.createRegion("PR4", ra);
    assertNotNull("PR4 not created", pr);
    int start = 1;
    int end = 50;
    int end2 = 100;
    // successful putIfAbsent
    for (int i = start; i <= end; i++) {
        Object putResult = pr.putIfAbsent(Integer.toString(i), Integer.toString(i));
        assertNull("Expected null, but got " + putResult + "for key " + i, putResult);
    }
    int size = pr.size();
    assertEquals("Size doesn't return expected value", end, size);
    assertFalse("isEmpty doesnt return proper state of the PartitionedRegion", pr.isEmpty());
    // unsuccessful putIfAbsent
    for (int i = start; i <= end; i++) {
        Object putResult = pr.putIfAbsent(Integer.toString(i), Integer.toString(i + 1));
        assertEquals("for i=" + i, Integer.toString(i), putResult);
        assertEquals("for i=" + i, Integer.toString(i), pr.get(Integer.toString(i)));
    }
    size = pr.size();
    assertEquals("Size doesn't return expected value", end, size);
    assertFalse("isEmpty doesnt return proper state of the PartitionedRegion", pr.isEmpty());
    // successful replace(Object, Object)
    for (int i = start; i <= end; i++) {
        Object replaceResult = pr.replace(Integer.toString(i), Integer.toString(-i));
        assertEquals("for i=" + i, Integer.toString(i), replaceResult);
        assertEquals("for i=" + i, Integer.toString(-i), pr.get(Integer.toString(i)));
    }
    size = pr.size();
    assertEquals("Size doesn't return expected value", end, size);
    assertFalse("isEmpty doesnt return proper state of the PartitionedRegion", pr.isEmpty());
    // unsuccessful replace(Object, Object)
    for (int i = end + 1; i <= end2; i++) {
        Object replaceResult = pr.replace(Integer.toString(i), Integer.toString(-i));
        assertNull("Expected null, but got " + replaceResult + "for i=" + i, replaceResult);
    }
    size = pr.size();
    assertEquals("Size doesn't return expected value", end, size);
    assertFalse("isEmpty doesnt return proper state of the PartitionedRegion", pr.isEmpty());
    // successful replace(Object key, Object oldValue, Object newValue)
    for (int i = start; i <= end; i++) {
        boolean replaceResult = pr.replace(Integer.toString(i), Integer.toString(-i), Integer.toString(i * 2));
        assertTrue("for i=" + i, replaceResult);
        assertEquals("for i=" + i, Integer.toString(i * 2), pr.get(Integer.toString(i)));
    }
    size = pr.size();
    assertEquals("Size doesn't return expected value", end, size);
    assertFalse("isEmpty doesnt return proper state of the PartitionedRegion", pr.isEmpty());
    // unsuccessful replace(Object key, Object oldValue, Object newValue)
    for (int i = start; i <= end2; i++) {
        boolean replaceResult = pr.replace(Integer.toString(i), Integer.toString(-i), Integer.toString(i * -4));
        assertFalse("for i=" + i, replaceResult);
        assertEquals("for i=" + i, i <= end ? Integer.toString(i * 2) : null, pr.get(Integer.toString(i)));
    }
    size = pr.size();
    assertEquals("Size doesn't return expected value", end, size);
    assertFalse("isEmpty doesnt return proper state of the PartitionedRegion", pr.isEmpty());
    // test unsuccessful remove(key, value)
    for (int i = start; i <= end2; i++) {
        boolean removeResult = pr.remove(Integer.toString(i), Integer.toString(-i));
        assertFalse("for i=" + i, removeResult);
        assertEquals("for i=" + i, i <= end ? Integer.toString(i * 2) : null, pr.get(Integer.toString(i)));
    }
    size = pr.size();
    assertEquals("Size doesn't return expected value", end, size);
    assertFalse("isEmpty doesnt return proper state of the PartitionedRegion", pr.isEmpty());
    // test successful remove(key, value)
    for (int i = start; i <= end; i++) {
        boolean removeResult = pr.remove(Integer.toString(i), Integer.toString(i * 2));
        assertTrue("for i=" + i, removeResult);
        assertEquals("for i=" + i, null, pr.get(Integer.toString(i)));
    }
    size = pr.size();
    assertEquals("Size doesn't return expected value", 0, size);
    assertTrue("isEmpty doesnt return proper state of the PartitionedRegion", pr.isEmpty());
}

@Test
public void testCurrentAllocatedMemory() throws Exception {
    PartitionedRegion regionAck1 = (PartitionedRegion) defineRegionFactory().create("testCurrentAllocatedemory");
    assertEquals(0, regionAck1.getDataStore().currentAllocatedMemory());
    Integer val1 = new Integer(16);
    regionAck1.put(new Integer(1), val1);
    Object storedVal = regionAck1.getBucketRegion(new Integer(1)).getRegionEntry(new Integer(1))._getValue();
    final int size1 = CachedDeserializableFactory.calcMemSize(storedVal);
    int size = size1;
    assertEquals(size, regionAck1.getDataStore().currentAllocatedMemory());
    byte[] val2 = new byte[1000];
    regionAck1.put(new Integer(2), val2);
    storedVal = regionAck1.getBucketRegion(new Integer(2)).getRegionEntry(new Integer(2))._getValue();
    final int size2 = CachedDeserializableFactory.calcMemSize(storedVal);
    size += size2;
    assertEquals(size, regionAck1.getDataStore().currentAllocatedMemory());
    String val3 = "0123456789";
    regionAck1.put(new Integer(3), val3);
    storedVal = regionAck1.getBucketRegion(new Integer(3)).getRegionEntry(new Integer(3))._getValue();
    final int size3 = CachedDeserializableFactory.calcMemSize(storedVal);
    size += size3;
    assertEquals(size, regionAck1.getDataStore().currentAllocatedMemory());
    long beforeSize = regionAck1.getDataStore().currentAllocatedMemory();
    regionAck1.invalidate(new Integer(3));
    size -= size3;
    assertEquals("beforeSize=" + beforeSize + " expectedSize=" + size + " afterSize=" + regionAck1.getDataStore().currentAllocatedMemory(), size, regionAck1.getDataStore().currentAllocatedMemory());
    assertEquals(size, regionAck1.getDataStore().currentAllocatedMemory());
    regionAck1.destroy(new Integer(3));
    assertEquals(size, regionAck1.getDataStore().currentAllocatedMemory());
    regionAck1.invalidate(new Integer(2));
    size -= size2;
    assertEquals(size, regionAck1.getDataStore().currentAllocatedMemory());
    regionAck1.destroy(new Integer(2));
    assertEquals(size, regionAck1.getDataStore().currentAllocatedMemory());
    regionAck1.invalidate(new Integer(1));
    size -= size1;
    assertEquals(size, regionAck1.getDataStore().currentAllocatedMemory());
    regionAck1.destroy(new Integer(1));
    assertEquals(size, regionAck1.getDataStore().currentAllocatedMemory());
    assertEquals(0, size);
    // Perform the destroy operations w/o the invalidate
    regionAck1.put(new Integer(2), val2);
    size += size2;
    assertEquals(size, regionAck1.getDataStore().currentAllocatedMemory());
    regionAck1.destroy(new Integer(2));
    size -= size2;
    assertEquals(size, regionAck1.getDataStore().currentAllocatedMemory());
    regionAck1.put(new Integer(3), val3);
    size += size3;
    assertEquals(size, regionAck1.getDataStore().currentAllocatedMemory());
    regionAck1.destroy(new Integer(3));
    size -= size3;
    assertEquals(size, regionAck1.getDataStore().currentAllocatedMemory());
    assertEquals(0, size);
}

