public void test() {
    final AtomicBoolean afterCreateInvoked = new AtomicBoolean();
    RegionListener listener = new RegionListener() {

        @Override
        public RegionAttributes beforeCreate(Region parent, String regionName, RegionAttributes attrs, InternalRegionArguments internalRegionArgs) {
            AttributesFactory newAttrsFactory = new AttributesFactory(attrs);
            newAttrsFactory.setDataPolicy(DataPolicy.EMPTY);
            return newAttrsFactory.create();
        }

        @Override
        public void afterCreate(Region region) {
            afterCreateInvoked.set(true);
        }
    };
    GemFireCacheImpl cache = (GemFireCacheImpl) new CacheFactory().set("mcast-port", "0").create();
    cache.addRegionListener(listener);
    Region region = cache.createRegionFactory(RegionShortcut.REPLICATE).create("region");
    assertEquals(DataPolicy.EMPTY, region.getAttributes().getDataPolicy());
    assertTrue(afterCreateInvoked.get());
}

/**
 * This test verifies the fix for GEODE-1199.
 * It verifies that when doNetWrite is called with an event
 * that has a StoredObject value that it will have "release"
 * called on it.
 */
@Test
public void verifyThatOffHeapReleaseIsCalledAfterNetWrite() {
    // setup
    SearchLoadAndWriteProcessor processor = SearchLoadAndWriteProcessor.getProcessor();
    LocalRegion lr = mock(LocalRegion.class);
    when(lr.getScope()).thenReturn(Scope.DISTRIBUTED_ACK);
    Object key = "key";
    StoredObject value = mock(StoredObject.class);
    when(value.hasRefCount()).thenReturn(true);
    when(value.retain()).thenReturn(true);
    Object cbArg = null;
    KeyInfo keyInfo = new KeyInfo(key, value, cbArg);
    when(lr.getKeyInfo(any(), any(), any())).thenReturn(keyInfo);
    processor.region = lr;
    EntryEventImpl event = EntryEventImpl.create(lr, Operation.REPLACE, key, value, cbArg, false, null);
    try {
        // the test
        processor.doNetWrite(event, null, null, 0);
        // verification
        verify(value, times(2)).retain();
        verify(value, times(1)).release();
    } finally {
        processor.release();
    }
}

