    Thread thread = Thread.currentThread();
    Transaction txn = (Transaction) tm.getTransactionMap().get(thread);
    txn.registerSynchronization(new Synchronization() {

        public void beforeCompletion() {
            fail("Notify Before Completion should not be called in rollback");
        }

        public void afterCompletion(int status) {
            assertTrue(status == Status.STATUS_ROLLEDBACK);
        }
    });
    txn.enlistResource(new XAResourceAdaptor() {
    });
    utx.rollback();
    assertTrue(tm.getGlobalTransactionMap().isEmpty());
    System.out.println("RolledBack successfully");
}

@Test
public void testBegin() throws Exception {
    utx.begin();
    Transaction txn = tm.getTransaction();
    assertNotNull("transaction not registered in the transaction map", txn);
    GlobalTransaction gtx = tm.getGlobalTransaction();
    assertNotNull("Global transaction not registered with the transaction manager", gtx);
    assertTrue("Transaction not added to the list", gtx.getTransactions().contains(txn));
    int status = gtx.getStatus();
    assertEquals("Transaction status not set to be active", Status.STATUS_ACTIVE, status);
    utx.commit();
}

@Test
public void testCommit() throws Exception {
