/**
 * A bunch of threads write a strictly increasing integer to log
 * "files" stored in byte arrays.  The files are merged and the
 * order is verified.
 */
@Test
public void testMultipleThreads() throws InterruptedException, IOException {
    // Spawn a bunch of threads that write to a log
    WorkerGroup group = new WorkerGroup("Workers");
    List workers = new ArrayList();
    for (int i = 0; i < 10; i++) {
        Worker worker = new Worker("Worker " + i, group);
        workers.add(worker);
        worker.start();
    }
    for (Iterator iter = workers.iterator(); iter.hasNext(); ) {
        Worker worker = (Worker) iter.next();
        ThreadUtils.join(worker, 120 * 1000);
    }
    if (group.exceptionOccurred()) {
        fail(group.getExceptionString());
    }
    // Merge the log files together
    InputStream[] streams = new InputStream[workers.size()];
    String[] names = new String[workers.size()];
    for (int i = 0; i < workers.size(); i++) {
        Worker worker = (Worker) workers.get(i);
        streams[i] = worker.getInputStream();
        names[i] = worker.getName();
    }
    StringWriter sw = new StringWriter();
    PrintWriter pw = new PrintWriter(sw, true);
    MergeLogFiles.mergeLogFiles(streams, names, pw);
    //System.out.println(sw.toString());
    // Verfiy that the entries are sorted
    BufferedReader br = new BufferedReader(new StringReader(sw.toString()));
    Pattern pattern = Pattern.compile("^Worker \\d+: .* VALUE: (\\d+)");
    int lastValue = -1;
    while (br.ready()) {
        String line = br.readLine();
        if (line == null) {
            break;
        }
        Matcher matcher = pattern.matcher(line);
        if (matcher.matches()) {
            int value = Integer.parseInt(matcher.group(1));
            assertTrue(lastValue + " <= " + value, value > lastValue);
            lastValue = value;
        }
    }
    assertEquals(999, lastValue);
}

/**
 * Generates a "log file" whose entry timestamps are in a random
 * order.  Then it sorts the log file and asserts that the entries
 * are sorted order.
 */
@Test
public void testRandomLog() throws Exception {
    ByteArrayOutputStream baos = new ByteArrayOutputStream();
    PrintWriter pw = new PrintWriter(new OutputStreamWriter(baos), true);
    LogWriter logger = new RandomLogWriter(pw);
    for (int i = 0; i < 100; i++) {
        logger.info(String.valueOf(i));
    }
    pw.flush();
    pw.close();
    byte[] bytes = baos.toByteArray();
    ByteArrayInputStream bais = new ByteArrayInputStream(bytes);
    StringWriter sw = new StringWriter();
    pw = new PrintWriter(sw, true);
    SortLogFile.sortLogFile(bais, pw);
    String sorted = sw.toString();
    BufferedReader br = new BufferedReader(new StringReader(sorted));
    LogFileParser parser = new LogFileParser(null, br);
    String prevTimestamp = null;
    while (parser.hasMoreEntries()) {
        LogFileParser.LogEntry entry = parser.getNextEntry();
        String timestamp = entry.getTimestamp();
        if (prevTimestamp != null) {
            assertTrue("Prev: " + prevTimestamp + ", current: " + timestamp, prevTimestamp.compareTo(timestamp) <= 0);
        }
        prevTimestamp = entry.getTimestamp();
    }
}

