    final String archiveFileName = dir + File.separator + testName + ".gfs";
    final LogWriterI18n log = new PureLogWriter(InternalLogWriter.CONFIG_LEVEL);
    final StatArchiveDescriptor archiveDescriptor = new StatArchiveDescriptor.Builder().setArchiveName(archiveFileName).setSystemId(1).setSystemStartTime(TestStatArchiveWriter.WRITER_INITIAL_DATE_MILLIS).setSystemDirectoryPath(testName).setProductDescription("StatArchiveWriterReaderJUnitTest").build();
    final StatArchiveWriter writer = new TestStatArchiveWriter(archiveDescriptor, log);
    final long sampleIncNanos = StatArchiveFormat.NANOS_PER_MILLI * 1000;
    try {
        writer.sampled(TestStatArchiveWriter.WRITER_PREVIOUS_TIMESTAMP_NANOS - sampleIncNanos, Collections.<ResourceInstance>emptyList());
