    assertEquals(0, uig.obtain());
    try {
        uig.obtain();
        fail("expected IllegalStateException");
    } catch (IllegalStateException expected) {
    }
    uig.release(0);
    assertEquals(0, uig.obtain());
    uig = new UniqueIdGenerator(32768);
    for (int i = 0; i < 32768; i++) {
