@Test
public void testCommandManagerCreateOption() throws Exception {
    CommandManager commandManager = CommandManager.getInstance(true);
    assertNotNull(commandManager);
    Method method = Commands.class.getMethod(COMMAND1_NAME, String.class, String.class, String.class, String.class, String.class);
    Annotation[][] annotations = method.getParameterAnnotations();
    Class<?>[] parameterTypes = method.getParameterTypes();
    List<String> optionNames = new ArrayList<String>();
    optionNames.add(OPTION1_NAME);
    optionNames.add(OPTION2_NAME);
    optionNames.add(OPTION3_NAME);
    int parameterNo = 0;
    for (int i = 0; i < annotations.length; i++) {
        Annotation[] annotation = annotations[i];
        for (Annotation ann : annotation) {
            if (ann instanceof CliOption) {
                Option createdOption = commandManager.createOption((CliOption) ann, parameterTypes[i], parameterNo);
                assertTrue(optionNames.contains(createdOption.getLongOption()));
                assertEquals(((CliOption) ann).help(), createdOption.getHelp());
                if (((CliOption) ann).specifiedDefaultValue() != null && ((CliOption) ann).specifiedDefaultValue().length() > 0) {
                    assertEquals(((CliOption) ann).specifiedDefaultValue().trim(), createdOption.getSpecifiedDefaultValue().trim());
                }
                if (((CliOption) ann).unspecifiedDefaultValue() != null && ((CliOption) ann).unspecifiedDefaultValue().length() > 0) {
                    assertEquals(((CliOption) ann).specifiedDefaultValue().trim(), createdOption.getSpecifiedDefaultValue().trim());
                }
            }
        }
    }
}

