            Cache cache = getCache();
            assertNotNull(cache);
            GemFireCacheImpl gfc = (GemFireCacheImpl) cache;
            Collection<DiskStoreImpl> diskStores = gfc.listDiskStores();
            assertNotNull(diskStores);
            assertTrue(diskStores.isEmpty());
            return null;
        }
    });
}

