        assertNotNull(result);
        assertEquals(Result.Status.OK, result.getStatus());
    } finally {
        assertEquals(Status.STOPPED, locatorLauncher.stop().getStatus());
        assertEquals(Status.NOT_RESPONDING, locatorLauncher.status().getStatus());
    }
}

