@Test
public void testExportStacktrace() throws ClassNotFoundException, IOException {
    setupSystem();
    File allStacktracesFile = new File("allStackTraces.txt");
    allStacktracesFile.createNewFile();
    allStacktracesFile.deleteOnExit();
