    input = command1Names[1] + " " + ARGUMENT1_COMPLETIONS[0].getValue() + SyntaxConstants.ARGUMENT_SEPARATOR + ARGUMENT2_COMPLETIONS[0].getValue() + SyntaxConstants.ARGUMENT_SEPARATOR + " " + SyntaxConstants.LONG_OPTION_SPECIFIER + OPTION1_NAME + SyntaxConstants.OPTION_VALUE_SPECIFIER + OPTION1_COMPLETIONS[0].getValue().substring(0, 2);
    clearAndAdvancedComplete(completionCandidates, completionValues, input, parser);
    // Here we expect the values for the first option
    for (Completion completion : OPTION1_COMPLETIONS) {
        if (completion.getValue().startsWith(OPTION1_COMPLETIONS[0].getValue().substring(0, 2))) {
            completionValues.add(new Completion(SyntaxConstants.OPTION_VALUE_SPECIFIER + completion.getValue(), completion.getValue(), null, 0));
        }
    }
    assertAdvancedCompletionValues(completionValues, completionCandidates);
    // Input contains command name, first argument, second argument,
    // first option and one of the values provided
    // by the auto-completor.
    input = command1Names[0] + " " + ARGUMENT1_COMPLETIONS[0].getValue() + SyntaxConstants.ARGUMENT_SEPARATOR + ARGUMENT2_COMPLETIONS[0].getValue() + SyntaxConstants.ARGUMENT_SEPARATOR + " " + SyntaxConstants.LONG_OPTION_SPECIFIER + OPTION1_NAME + SyntaxConstants.OPTION_VALUE_SPECIFIER + OPTION1_COMPLETIONS[0].getValue();
    clearAndAdvancedComplete(completionCandidates, completionValues, input, parser);
    // Here we expect the remaining options
    // As only first option is mandatory, we expect the
    // the other non-mandatory options.
    completionValues.add(new Completion(" " + SyntaxConstants.LONG_OPTION_SPECIFIER + OPTION2_NAME, OPTION2_NAME, null, 0));
    completionValues.add(new Completion(" " + SyntaxConstants.LONG_OPTION_SPECIFIER + OPTION3_NAME, OPTION3_NAME, null, 0));
    assertAdvancedCompletionValues(completionValues, completionCandidates);
    // Input contains command name, first argument, second argument,
    // first option, one value for the option and value separator at
    // the end
    input = command1Names[0] + " " + ARGUMENT1_COMPLETIONS[0].getValue() + SyntaxConstants.ARGUMENT_SEPARATOR + ARGUMENT2_COMPLETIONS[0].getValue() + SyntaxConstants.ARGUMENT_SEPARATOR + " " + SyntaxConstants.LONG_OPTION_SPECIFIER + OPTION1_NAME + SyntaxConstants.OPTION_VALUE_SPECIFIER + OPTION1_COMPLETIONS[0].getValue() + SyntaxConstants.VALUE_SEPARATOR;
    clearAndAdvancedComplete(completionCandidates, completionValues, input, parser);
    // Here we expect the other values for completion
    completionValues.add(new Completion(SyntaxConstants.VALUE_SEPARATOR + OPTION1_COMPLETIONS[1].getValue(), OPTION1_COMPLETIONS[1].getValue(), null, 0));
    assertAdvancedCompletionValues(completionValues, completionCandidates);
    // Input contains command name, first argument, second argument,
    // first option and both the values for the option
    input = command1Names[0] + " " + ARGUMENT1_COMPLETIONS[0].getValue() + SyntaxConstants.ARGUMENT_SEPARATOR + ARGUMENT2_COMPLETIONS[0].getValue() + SyntaxConstants.ARGUMENT_SEPARATOR + " " + SyntaxConstants.LONG_OPTION_SPECIFIER + OPTION1_NAME + SyntaxConstants.OPTION_VALUE_SPECIFIER + OPTION1_COMPLETIONS[0].getValue() + SyntaxConstants.VALUE_SEPARATOR + OPTION1_COMPLETIONS[1].getValue();
    clearAndAdvancedComplete(completionCandidates, completionValues, input, parser);
    // Here we expect the remaining options
    // As only first option is mandatory, we expect the
    // the other non-mandatory options.
    completionValues.add(new Completion(" " + SyntaxConstants.LONG_OPTION_SPECIFIER + OPTION2_NAME, OPTION2_NAME, null, 0));
    completionValues.add(new Completion(" " + SyntaxConstants.LONG_OPTION_SPECIFIER + OPTION3_NAME, OPTION3_NAME, null, 0));
    assertAdvancedCompletionValues(completionValues, completionCandidates);
    // Input contains command name, first argument, second argument,
    // first option, both the values for the option and valueSeparator
    // at the end
    input = command1Names[0] + " " + ARGUMENT1_COMPLETIONS[0].getValue() + SyntaxConstants.ARGUMENT_SEPARATOR + ARGUMENT2_COMPLETIONS[0].getValue() + SyntaxConstants.ARGUMENT_SEPARATOR + " " + SyntaxConstants.LONG_OPTION_SPECIFIER + OPTION1_NAME + SyntaxConstants.OPTION_VALUE_SPECIFIER + OPTION1_COMPLETIONS[0].getValue() + SyntaxConstants.VALUE_SEPARATOR + OPTION1_COMPLETIONS[1].getValue() + SyntaxConstants.VALUE_SEPARATOR;
    clearAndAdvancedComplete(completionCandidates, completionValues, input, parser);
    // Here we expect nothing for completion
    assertAdvancedCompletionValues(completionValues, completionCandidates);
    // Input contains command name, first argument, second argument,
    // first option and multiple values assigned to it. It also contains
    // start of the second option
    input = command1Names[0] + " " + ARGUMENT1_COMPLETIONS[0].getValue() + SyntaxConstants.ARGUMENT_SEPARATOR + ARGUMENT2_COMPLETIONS[0].getValue() + SyntaxConstants.ARGUMENT_SEPARATOR + " " + SyntaxConstants.LONG_OPTION_SPECIFIER + OPTION1_NAME + SyntaxConstants.OPTION_VALUE_SPECIFIER + OPTION1_COMPLETIONS[0].getValue() + SyntaxConstants.VALUE_SEPARATOR + OPTION1_COMPLETIONS[1].getValue() + " " + SyntaxConstants.LONG_OPTION_SPECIFIER + OPTION2_NAME.substring(0, 3);
    clearAndAdvancedComplete(completionCandidates, completionValues, input, parser);
    // Here we expect those options which have not been specified
    // before and which have the prefix specified herein as their
    // prefix
    completionValues.add(new Completion(" " + SyntaxConstants.LONG_OPTION_SPECIFIER + OPTION2_NAME, OPTION2_NAME, null, 0));
    if (OPTION3_NAME.startsWith(OPTION2_NAME.substring(0, 3))) {
        completionValues.add(new Completion(" " + SyntaxConstants.LONG_OPTION_SPECIFIER + OPTION3_NAME, OPTION3_NAME, null, 0));
    }
    assertAdvancedCompletionValues(completionValues, completionCandidates);
}

/**
 * Test for checking parsing of {@link GfshParser} with method
 * {@link GfshParser#parse(String)}
 *
 * Does not include testing for multiple values as this change is still
 * pending in spring-shell
 */
@Test
public void testParse() throws Exception {
    // Get the names of the command
    String[] command1Names = ((CliCommand) methodCommand1.getAnnotation(CliCommand.class)).value();
    // Input contains an entirely different string
    String input = "moc";
    ParseResult parse = null;
    CommandProcessingException expectedException = null;
    try {
        parse = parser.parse(input);
    } catch (CommandProcessingException expected) {
        expectedException = expected;
    } finally {
        assertNotNull("Expecting a " + CommandProcessingException.class + " for an invalid command name: " + input, expectedException);
        assertEquals("CommandProcessingException type doesn't match. " + "Actual(" + expectedException.getErrorType() + ") & Expected(" + CommandProcessingException.COMMAND_INVALID_OR_UNAVAILABLE + ") ", expectedException.getErrorType(), CommandProcessingException.COMMAND_INVALID_OR_UNAVAILABLE);
    }
    // Input contains a string which is prefix
    // of more than 1 command
    input = "c";
    expectedException = null;
    try {
        parse = parser.parse(input);
    } catch (CommandProcessingException e) {
        expectedException = e;
    } finally {
        assertNotNull("Expecting a " + CommandProcessingException.class + " for an invalid/incomplete command name: " + input, expectedException);
        assertEquals("CommandProcessingException type doesn't match. Actual(" + expectedException.getErrorType() + ") & Expected(" + CommandProcessingException.COMMAND_INVALID_OR_UNAVAILABLE + ") ", expectedException.getErrorType(), CommandProcessingException.COMMAND_INVALID_OR_UNAVAILABLE);
    }
    // Input contains only prefix of the command
    // name which is not a prefix of other command.
    // It may be the prefix for the synonym of command
    input = "com";
    expectedException = null;
    try {
        parse = parser.parse(input);
    } catch (CommandProcessingException expected) {
        expectedException = expected;
    } finally {
        //FIXME - Nikhil/Abhishek prefix shouldn't work
        assertNotNull("Expecting a " + CommandProcessingException.class + " for an invalid/incomplete command name: " + input, expectedException);
        assertEquals("CommandProcessingException type doesn't match. Actual(" + expectedException.getErrorType() + ") & Expected(" + CommandProcessingException.COMMAND_INVALID_OR_UNAVAILABLE + ") ", expectedException.getErrorType(), CommandProcessingException.COMMAND_INVALID_OR_UNAVAILABLE);
    }
    // Input contains only command name
    input = command1Names[0];
    expectedException = null;
    try {
        parse = parser.parse(input);
    } catch (CommandProcessingException expected) {
        expectedException = expected;
    } finally {
        assertNotNull("Expecting a " + CommandProcessingException.class + " for an invalid/incomplete command name: " + input, expectedException);
        assertEquals("CommandProcessingException type doesn't match. Actual(" + expectedException.getErrorType() + ") & Expected(" + CommandProcessingException.REQUIRED_ARGUMENT_MISSING + ") ", CommandProcessingException.REQUIRED_ARGUMENT_MISSING, expectedException.getErrorType());
    }
    // Input contains first argument and first option with value
    input = command1Names[0] + " ARGUMENT1_VALUE " + SyntaxConstants.LONG_OPTION_SPECIFIER + OPTION1_NAME + SyntaxConstants.OPTION_VALUE_SPECIFIER + "somevalue";
    parse = parser.parse(input);
    assertNotNull(parse);
    assertEquals("Check ParseResult method", parse.getMethod(), methodCommand1);
    assertEquals("Check no. of method arguments", 5, parse.getArguments().length);
    assertEquals("Check argument1", "ARGUMENT1_VALUE", parse.getArguments()[0]);
    assertEquals("Check argument2", ARGUMENT2_UNSPECIFIED_DEFAULT_VALUE, parse.getArguments()[1]);
    assertEquals("Check option1 value", "somevalue", parse.getArguments()[2]);
    assertEquals("Check option2 value", null, parse.getArguments()[3]);
    assertEquals("Check option3 value", OPTION3_UNSPECIFIED_DEFAULT_VALUE, parse.getArguments()[4]);
    // Input contains only both arguments but is terminated by long option
    // specifiers. These hyphens at the end are ignored by the parser
    input = command1Names[1] + " ARGUMENT1_VALUE?      ARGUMENT2_VALUE -- ----------";
    try {
        parse = parser.parse(input);
    } catch (CommandProcessingException expected) {
        expectedException = expected;
    } finally {
        assertNotNull("Expecting a " + CommandProcessingException.class + " for an invalid/incomplete command name: " + input, expectedException);
        assertEquals("CommandProcessingException type doesn't match. Actual(" + expectedException.getErrorType() + ") & Expected(" + CommandProcessingException.REQUIRED_OPTION_MISSING + ") ", expectedException.getErrorType(), CommandProcessingException.REQUIRED_OPTION_MISSING);
    }
    // Input contains both arguments. The first option is specified with value
    // The second is specified without value and the third option is not
    // specified
    input = command1Names[1] + "         ARGUMENT1_VALUE?       ARGUMENT2_VALUE " + SyntaxConstants.LONG_OPTION_SPECIFIER + OPTION1_NAME + SyntaxConstants.OPTION_VALUE_SPECIFIER + "option1value" + " " + SyntaxConstants.LONG_OPTION_SPECIFIER + OPTION2_NAME;
    parse = parser.parse(input);
    assertNotNull(parse);
    assertEquals("Check ParseResult method", parse.getMethod(), methodCommand1);
    assertEquals("Check no. of method arguments", 5, parse.getArguments().length);
    assertEquals("Check argument1", "ARGUMENT1_VALUE", parse.getArguments()[0]);
    assertEquals("Check argument2", "ARGUMENT2_VALUE", parse.getArguments()[1]);
    assertEquals("Check option1 value", "option1value", parse.getArguments()[2]);
    assertEquals("Check option2 value", OPTION2_SPECIFIED_DEFAULT_VALUE, parse.getArguments()[3]);
    assertEquals("Check option3 value", OPTION3_UNSPECIFIED_DEFAULT_VALUE, parse.getArguments()[4]);
    // Input contains both arguments. All the three options
    // are specified with values
    input = command1Names[1] + "         ARGUMENT1_VALUE?       ARGUMENT2_VALUE " + SyntaxConstants.LONG_OPTION_SPECIFIER + OPTION1_SYNONYM + SyntaxConstants.OPTION_VALUE_SPECIFIER + "option1value" + " " + SyntaxConstants.LONG_OPTION_SPECIFIER + OPTION2_NAME + SyntaxConstants.OPTION_VALUE_SPECIFIER + "option2value" + " " + SyntaxConstants.LONG_OPTION_SPECIFIER + OPTION3_NAME + SyntaxConstants.OPTION_VALUE_SPECIFIER + "option3value";
    parse = parser.parse(input);
    assertNotNull(parse);
    assertEquals("Check ParseResult method", parse.getMethod(), methodCommand1);
    assertEquals("Check no. of method arguments", 5, parse.getArguments().length);
    assertEquals("Check argument1", "ARGUMENT1_VALUE", parse.getArguments()[0]);
    assertEquals("Check argument2", "ARGUMENT2_VALUE", parse.getArguments()[1]);
    assertEquals("Check option1 value", "option1value", parse.getArguments()[2]);
    assertEquals("Check option2 value", "option2value", parse.getArguments()[3]);
    assertEquals("Check option3 value", "option3value", parse.getArguments()[4]);
    // Test concatenation of options when they appear more than once in the command
    String command = "testParamConcat --string=string1 --stringArray=1,2 --stringArray=3,4 --stringList=11,12,13 --integer=10 --stringArray=5 --stringList=14,15";
    ParseResult parseResult = parser.parse(command);
    assertNotNull(parseResult);
    assertEquals("Check ParseResult method", parseResult.getMethod(), methodTestParamConcat);
    assertEquals("Check no. of method arguments", 5, parseResult.getArguments().length);
    Object[] arguments = parseResult.getArguments();
    assertEquals(arguments[0], "string1");
    assertEquals(((String[]) arguments[1])[0], "1");
    assertEquals(((String[]) arguments[1])[1], "2");
    assertEquals(((String[]) arguments[1])[2], "3");
    assertEquals(((String[]) arguments[1])[3], "4");
    assertEquals(((String[]) arguments[1])[4], "5");
    assertEquals(((List) arguments[2]).get(0), "11");
    assertEquals(((List) arguments[2]).get(1), "12");
    assertEquals(((List) arguments[2]).get(2), "13");
    assertEquals(((List) arguments[2]).get(3), "14");
    assertEquals(((List) arguments[2]).get(4), "15");
    assertEquals(arguments[3], 10);
    // Test concatenation of options when they appear more than once in the command
    command = "testParamConcat --stringArray=1,2 --stringArray=\'3,4\'";
    parseResult = parser.parse(command);
    assertNotNull(parseResult);
    assertEquals("Check ParseResult method", parseResult.getMethod(), methodTestParamConcat);
    assertEquals("Check no. of method arguments", 5, parseResult.getArguments().length);
    arguments = parseResult.getArguments();
    assertEquals(((String[]) arguments[1])[0], "1");
    assertEquals(((String[]) arguments[1])[1], "2");
    assertEquals(((String[]) arguments[1])[2], "3,4");
    command = "testParamConcat --string=\"1\" --colonArray=2:3:4 --stringArray=5,\"6,7\",8 --stringList=\"9,10,11,12\"";
    parseResult = parser.parse(command);
    assertNotNull(parseResult);
    assertEquals("Check ParseResult method", parseResult.getMethod(), methodTestParamConcat);
    assertEquals("Check no. of method arguments", 5, parseResult.getArguments().length);
    arguments = parseResult.getArguments();
    assertEquals(arguments[0], "1");
    assertEquals(((String[]) arguments[1])[0], "5");
    assertEquals(((String[]) arguments[1])[1], "6,7");
    assertEquals(((String[]) arguments[1])[2], "8");
    assertEquals(((List) arguments[2]).get(0), "9,10,11,12");
    assertEquals(((String[]) arguments[4])[0], "2");
    assertEquals(((String[]) arguments[4])[1], "3");
    assertEquals(((String[]) arguments[4])[2], "4");
    try {
        command = "testParamConcat --string=string1 --stringArray=1,2 --string=string2";
        parseResult = parser.parse(command);
        fail("Should have received a CommandProcessingException due to 'string' being specified twice");
    } catch (CommandProcessingException expected) {
        // Expected
    }
    command = "testMultiWordArg this is just one argument?this is a second argument";
    parseResult = parser.parse(command);
    assertNotNull(parseResult);
    assertEquals("Check ParseResult method", parseResult.getMethod(), methodTestMultiWordArg);
    assertEquals("Check no. of method arguments", 2, parseResult.getArguments().length);
    arguments = parseResult.getArguments();
    assertEquals(arguments[0], "this is just one argument");
    assertEquals(arguments[1], "this is a second argument");
}

