/**
 * As of 8.1 the cache type requires that certain elements be listed in
 * sequence. This test verifies that
 * {@link CacheElement#buildElementMap(Document)} produces a mapping in the
 * correct order. If we change to use choice for all elements then we can
 * abandon this mapping.
 *
 * @since 8.1
 */
@Test
public void testBuildElementMap() throws Exception {
    final Document doc = XmlUtils.createDocumentFromReader(new InputStreamReader(this.getClass().getResourceAsStream("CacheElementJUnitTest.xml")));
    final LinkedHashMap<String, CacheElement> elementMap = CacheElement.buildElementMap(doc);
    final Iterator<Entry<String, CacheElement>> entries = elementMap.entrySet().iterator();
    int order = 0;
    assertEntry("cache-transaction-manager", order++, entries.next());
    assertEntry("dynamic-region-factory", order++, entries.next());
    assertEntry("gateway-hub", order++, entries.next());
    assertEntry("gateway-sender", order++, entries.next());
    assertEntry("gateway-receiver", order++, entries.next());
    assertEntry("gateway-conflict-resolver", order++, entries.next());
    assertEntry("async-event-queue", order++, entries.next());
    assertEntry("cache-server", order++, entries.next());
    assertEntry("pool", order++, entries.next());
    assertEntry("disk-store", order++, entries.next());
    assertEntry("pdx", order++, entries.next());
    assertEntry("region-attributes", order++, entries.next());
    assertEntry("jndi-bindings", order++, entries.next());
    assertEntry("region", order++, entries.next());
    assertEntry("vm-root-region", order++, entries.next());
    assertEntry("function-service", order++, entries.next());
    assertEntry("resource-manager", order++, entries.next());
    assertEntry("serialization-registration", order++, entries.next());
    assertEntry("backup", order++, entries.next());
    assertEntry("initializer", order++, entries.next());
    assertTrue("Extra entries in map.", !entries.hasNext());
}

@Test
public void testGetHostedLocatorsWithSharedConfiguration() throws Exception {
    final VM locator1Vm = getHost(0).getVM(1);
    final VM locator2Vm = getHost(0).getVM(2);
    final String testName = getName();
    final int[] ports = getRandomAvailableTCPPorts(3);
    final int locator1Port = ports[0];
    final String locator1Name = "locator1" + locator1Port;
    locator1Vm.invoke(new SerializableCallable() {

        @Override
        public Object call() {
            final File locatorLogFile = new File(testName + "-locator-" + locator1Port + ".log");
            final Properties locatorProps = new Properties();
            locatorProps.setProperty(NAME_NAME, locator1Name);
            locatorProps.setProperty(MCAST_PORT_NAME, "0");
            locatorProps.setProperty(LOG_LEVEL_NAME, "fine");
            locatorProps.setProperty(ENABLE_CLUSTER_CONFIGURATION_NAME, "true");
            try {
                final InternalLocator locator = (InternalLocator) Locator.startLocatorAndDS(locator1Port, locatorLogFile, null, locatorProps);
                WaitCriterion wc = new WaitCriterion() {

                    @Override
                    public boolean done() {
                        return locator.isSharedConfigurationRunning();
                    }

                    @Override
                    public String description() {
                        return "Waiting for shared configuration to be started";
                    }
                };
                waitForCriterion(wc, TIMEOUT, INTERVAL, true);
            } catch (IOException e) {
                fail("Unable to create a locator with a shared configuration", e);
            }
            GemFireCacheImpl cache = GemFireCacheImpl.getInstance();
            InternalDistributedMember me = cache.getMyId();
            DM dm = cache.getDistributionManager();
            Map<InternalDistributedMember, Collection<String>> hostedLocators = dm.getAllHostedLocators();
            assertFalse(hostedLocators.isEmpty());
            Map<InternalDistributedMember, Collection<String>> hostedLocatorsWithSharedConfiguration = dm.getAllHostedLocatorsWithSharedConfiguration();
            assertFalse(hostedLocatorsWithSharedConfiguration.isEmpty());
            assertNotNull(hostedLocators.get(me));
            assertNotNull(hostedLocatorsWithSharedConfiguration.get(me));
