    assertEquals(5, bs.position());
    try {
        bytes = new byte[6];
        bs.get(bytes);
        fail("expected BufferUnderflowException");
    } catch (BufferUnderflowException expected) {
    }
    bytes = new byte[5];
    bs.get(bytes);
    assertArrayEquals(new byte[] { 6, 7, 8, 9, 0 }, bytes);
    assertEquals(10, bs.position());
    bytes = new byte[0];
    bs.get(bytes);
    assertEquals(10, bs.position());
    try {
        bytes = new byte[1];
        bs.get(bytes);
        fail("expected BufferUnderflowException");
    } catch (BufferUnderflowException expected) {
    }
}

