        assertEquals(new SimpleClass(2, (byte) 2), r2.get(new SimpleClass(2, (byte) 2)));
        this.c.close();
        // use a cache.xml to recover
        this.c = (GemFireCacheImpl) new CacheFactory().set("mcast-port", "0").create();
