    assertTrue(!reg1.containsKey("key1"));
    // first invocation
    assertEquals("LV 15", reg1.get("key1"));
    assertTrue(reg1.containsKey("key1"));
    assertEquals("LV 15", reg1.getEntry("key1").getValue());
    reg1.localInvalidate("key1");
    // second invocation
