        getLogWriter().info("testGatewaySenderStatus : " + strCmdResult + ">>>>> ");
        assertEquals(Result.Status.OK, cmdResult.getStatus());
    } else {
        fail("testListGatewaySender failed as did not get CommandResult");
    }
